<?php
require __DIR__.'/config/bootstrap.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=db()->prepare('INSERT INTO transactions(property_id,client_id,transaction_type,amount,commission,transaction_date,notes) VALUES(?,?,?,?,?,?,?)');$st->execute([(int)$_POST['property_id'],($_POST['client_id']??'')?:null,$_POST['transaction_type'],$_POST['amount'],$_POST['commission'],$_POST['transaction_date'],$_POST['notes']??'']);$newStatus=$_POST['transaction_type']==='Sale'?'Sold':'Rented';$up=db()->prepare('UPDATE properties SET status=? WHERE id=?');$up->execute([$newStatus,(int)$_POST['property_id']]);flash('success','Transaction recorded and property status updated.');redirect('transactions.php');}
$props=db()->query("SELECT id,property_code,title FROM properties WHERE status IN ('Available','Reserved') ORDER BY title")->fetchAll();$clients=db()->query('SELECT id,full_name FROM clients ORDER BY full_name')->fetchAll();$rows=db()->query('SELECT t.*,p.title,c.full_name FROM transactions t JOIN properties p ON p.id=t.property_id LEFT JOIN clients c ON c.id=t.client_id ORDER BY t.transaction_date DESC')->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="page-title mb-3">Sales & Commission</div><div class="row g-3"><div class="col-lg-4"><div class="panel"><h6>Record Transaction</h6><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label class="form-label">Property</label><select class="form-select mb-2" name="property_id" required><?php foreach($props as $p): ?><option value="<?=$p['id']?>"><?=h($p['property_code'].' - '.$p['title'])?></option><?php endforeach; ?></select><label class="form-label">Client</label><select class="form-select mb-2" name="client_id"><option value="">Select client</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>"><?=h($c['full_name'])?></option><?php endforeach; ?></select><label class="form-label">Type</label><select class="form-select mb-2" name="transaction_type"><option>Sale</option><option>Rental</option></select><label class="form-label">Amount (PHP)</label><input class="form-control mb-2" type="number" step=".01" name="amount" required><label class="form-label">Commission (PHP)</label><input class="form-control mb-2" type="number" step=".01" name="commission" value="0" required><label class="form-label">Date</label><input class="form-control mb-2" type="date" name="transaction_date" value="<?=date('Y-m-d')?>" required><label class="form-label">Notes</label><textarea class="form-control mb-3" name="notes"></textarea><button class="btn btn-primary w-100">Save Transaction</button></form></div></div><div class="col-lg-8"><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Property / Client</th><th>Type</th><th>Amount</th><th>Commission</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=h($r['title'])?><div class="small text-secondary"><?=h($r['full_name']??'No client selected')?></div></td><td><?=h($r['transaction_type'])?></td><td>₱<?=number_format((float)$r['amount'],2)?></td><td>₱<?=number_format((float)$r['commission'],2)?></td><td><?=h($r['transaction_date'])?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty-state">No transactions yet.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
